import { ConvertibleUnit, ConvertibleTarget } from './types';
/**
 * Converts a given number to the specified unit. Example:
 * ```typescript
 * import { convert, units } from "@dynatrace-sdk/units";
 * convert(1500, units.length.meter, units.length.kilometer) // 1.5
 * ```
 * @param input The number that will get converted.
 * @param from The unit of the input (e.g. `units.length.meter`).
 * @param to The unit of the output (e.g. `units.length.kilometer`).
 * @returns The result of the conversion (e.g. `1.5`).
 */
export declare function convert<FromUnit extends ConvertibleUnit, ToUnit extends ConvertibleUnit>(input: number, from: FromUnit, to: ConvertibleTarget<FromUnit, ToUnit>): number;
